295	    /**
296	     * The owner's membership points, the score the {@link #getMembershipLevel() membership level} is
297	     * derived from. The score starts at 0 and gains: 2 when an email address is present, 1 when the
298	     * owner has no namesakes ({@code namesakeCount} is 0), 2 for a household of 3 or more members
299	     * ({@code householdSize} is at least 3), and 3 when the owner's tenure exceeds 365 days (see
300	     * {@link #getTenureDays()}). Because a newly created owner has zero tenure, the tenure points are
301	     * never awarded at create time.
302	     *
303	     * @return the membership points, a non-negative integer
304	     */
305	    public Integer getMembershipPoints() {
306	        int points = 0;
307	        boolean hasEmail = this.email != null && !this.email.isBlank();
308	        if (hasEmail) {
309	            points += 2;
310	        }
311	        boolean hasNoNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
312	        if (hasNoNamesakes) {
313	            points += 1;
314	        }
315	        if (this.householdSize != null && this.householdSize >= 3) {
316	            points += 2;
317	        }
318	        Long tenureDays = getTenureDays();
319	        if (tenureDays != null && tenureDays > 365) {
320	            points += 3;
321	        }
322	        return points;
323	    }
