325	    /**
326	     * The owner's numeric membership level, mapped from the {@link #getMembershipPoints() membership
327	     * points}: level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and level 4
328	     * for 6 or more points.
329	     *
330	     * @return the membership level, an integer from 1 to 4
331	     */
332	    public Integer getMembershipLevel() {
333	        int points = getMembershipPoints();
334	        if (points <= 1) {
335	            return 1;
336	        }
337	        if (points <= 3) {
338	            return 2;
339	        }
340	        if (points <= 5) {
341	            return 3;
342	        }
343	        return 4;
344	    }
