381	    /**
382	     * The owner's IANA timezone name, derived from the owner's {@link #getLocality() locality} via the
383	     * fixed region-to-timezone table: NSW->Australia/Sydney, VIC->Australia/Melbourne,
384	     * QLD->Australia/Brisbane. Returns {@code null} when the locality is not one of these regions (for
385	     * example the {@code 'UNKNOWN'} locality of a city with no known region).
386	     *
387	     * @return the IANA timezone name, or {@code null} when the locality has no mapped timezone
388	     */
389	    public String getTimezone() {
390	        return REGION_TIMEZONE.get(getLocality());
391	    }
