393	    /**
394	     * The region the customer code's {@code <REGION>} component is built from: the postcode looked up
395	     * by range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), falling back to the fixed
396	     * city-to-region table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the postcode is absent or
397	     * in no known range, and {@code 'UNKNOWN'} when neither resolves. Preferring the postcode returns
398	     * the same region for known cities but disambiguates cities that share a name.
399	     *
400	     * @return the canonical region string, or {@code 'UNKNOWN'}
401	     */
402	    private String deriveRegion() {
403	        String region = regionFromPostcode();
404	        if (region != null) {
405	            return region;
406	        }
407	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
408	    }
