410	    /**
411	     * Builds this owner's customer code, formatted {@code '<REGION>-<HASH8>'}. {@code REGION} is the
412	     * region derived from the postcode (falling back to the city, then {@code 'UNKNOWN'}; see
413	     * {@link #deriveRegion()}) and {@code HASH8} is the first 8 upper-case hexadecimal characters of
414	     * the SHA-256 digest of the owner's normalized telephone concatenated with its last name (e.g.
415	     * {@code 'NSW-1A2B3C4D'}). The code carries no sequence number, so it is a pure function of the
416	     * owner's region, telephone and last name. Call this once at create time and store the result via
417	     * {@link #setCustomerCode(String)}, which thereafter backs {@link #getLocality()},
418	     * {@link #getMembershipNumber()} and {@link #getCheckDigit()}.
419	     *
420	     * @return the assembled customer code
421	     */
422	    public String buildCustomerCode() {
423	        return deriveRegion() + "-" + sha256Hex8(this.telephone + this.getLastName());
424	    }
425	
426	    /**
427	     * Computes the first 8 upper-case hexadecimal characters (the first 4 bytes) of the SHA-256 digest
428	     * of the given value's UTF-8 bytes, the {@code HASH8} component of the customer code.
429	     *
430	     * @param value the value to hash
431	     * @return the 8-character upper-case hex prefix of the SHA-256 digest
432	     */
433	    private static String sha256Hex8(String value) {
434	        try {
435	            byte[] digest = MessageDigest.getInstance("SHA-256")
436	                .digest(value.getBytes(StandardCharsets.UTF_8));
437	            StringBuilder hex = new StringBuilder(8);
438	            for (int i = 0; i < 4; i++) {
439	                hex.append(String.format("%02X", digest[i]));
440	            }
441	            return hex.toString();
442	        }
443	        catch (NoSuchAlgorithmException e) {
444	            throw new IllegalStateException("SHA-256 algorithm not available", e);
445	        }
446	    }
