448	    /**
449	     * The region whose range contains this owner's postcode, or {@code null} when the postcode is
450	     * absent, not a 4-digit number, or in no known range.
451	     *
452	     * @return the matching region, or {@code null}
453	     */
454	    private String regionFromPostcode() {
455	        if (this.postcode == null) {
456	            return null;
457	        }
458	        int value;
459	        try {
460	            value = Integer.parseInt(this.postcode.trim());
461	        }
462	        catch (NumberFormatException ex) {
463	            return null;
464	        }
465	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE.entrySet()) {
466	            int[] range = entry.getValue();
467	            if (value >= range[0] && value <= range[1]) {
468	                return entry.getKey();
469	            }
470	        }
471	        return null;
472	    }
