557	    /**
558	     * Stamps the effective registration date exactly once on insert, so every newly persisted owner
559	     * carries a resolved, business-day registration date (see {@link #resolveRegistrationDate}).
560	     */
561	    @PrePersist
562	    void onCreate() {
563	        this.registrationDate = resolveRegistrationDate(this.registrationDate);
564	    }
